#!/bin/bash

# psql --host=0.0.0.0 -p2137 -U postgres -e -E


docker kill bioseqdb-instance; docker rm bioseqdb-instance 2> /dev/null > /dev/null

#docker build . -t bioseqdb

docker run \
-p 2137:5432 \
--name bioseqdb-instance \
-e POSTGRES_PASSWORD=mypassword \
-e PGDATA=/var/lib/postgresql/data/pgdata \
-v data:/var/lib/postgresql/data \
unneon/bioseqdb

# psql --host=0.0.0.0 -p2137 -U postgres

DROP TABLE IF EXISTS dataset CASCADE;
DROP EXTENSION IF EXISTS bioseqdb CASCADE;
DROP TYPE IF EXISTS sex CASCADE;

CREATE EXTENSION bioseqdb;
CREATE TYPE sex AS ENUM ('Female', 'Male');
CREATE TABLE dataset (
    id serial primary key not null,
    strain varchar(60) not null,
    seq nuclseq not null,
    retrieval_date date,
    submitted_date date,
    region varchar (60),
	country varchar (60),
	country_code varchar (2),
    division varchar (60),
    location varchar (60),
    age interval,
    sex sex,
    lineage varchar(60)
);

INSERT INTO dataset (
    retrieval_date, submitted_date, region, country, country_code, division, location, age, sex, lineage, strain,
    seq
)
