INSERT INTO dataset (
    retrieval_date, submitted_date, region, country, country_code, division, location, age, sex, lineage, strain,
    seq
)
VALUES (
    '2025-03-14','2017-03-14','Europe','Poland','PL','Mazovian','Warsaw','21 years'::interval,'Female','default','default',
    'ACTAGTAGTAGAAAAAATTTGATGATGATTGGGATGGAACATTCTGTTACACAAATTGATTGATGGATTGATTCGACAAAGCTAAACACC'
);

SELECT
ref_id, query_id, ref_match_start, ref_match_end, ref_match_len, query_match_start, query_match_end, query_match_len, is_primary, is_secondary, is_reverse, cigar, score
FROM nuclseq_multi_search_bwa('SELECT id, seq FROM dataset', 'SELECT id, seq FROM dataset')
ORDER BY
score DESC;



